(function() {
  const state = {
    cases: [],
    summary: {},
    insights: {},
    sortedBy: null,
    sortedDirection: 'asc',
    isLoading: false,
    error: null,
    lastRefreshTime: null
  };

  function generateMockData() {
    const priorities = ['High', 'Medium', 'Low'];
    const statuses = ['New', 'Working', 'Escalated', 'Pending'];
    const accounts = ['Acme Corp', 'Global Industries', 'Tech Solutions', 'Enterprise LLC', 'Innovation Inc'];
    const subjects = [
      'System Integration Issue',
      'Performance Degradation',
      'Feature Request',
      'Bug Report',
      'Configuration Help',
      'Data Migration',
      'Access Problem',
      'Training Request'
    ];

    const cases = [];
    for (let i = 1; i <= 12; i++) {
      const daysOpen = Math.floor(Math.random() * 30) + 1;
      const slaDaysRemaining = Math.floor(Math.random() * 15) - 2;
      cases.push({
        caseId: `case-${i}`,
        caseNumber: `CASE-${10000 + i}`,
        subject: subjects[Math.floor(Math.random() * subjects.length)],
        priority: priorities[Math.floor(Math.random() * priorities.length)],
        status: statuses[Math.floor(Math.random() * statuses.length)],
        daysOpen: daysOpen,
        slaDaysRemaining: slaDaysRemaining,
        accountName: accounts[Math.floor(Math.random() * accounts.length)],
        isEscalated: Math.random() > 0.7
      });
    }

    const summary = {
      totalOpen: cases.length,
      slaRiskCount: cases.filter(c => c.slaDaysRemaining < 2).length,
      escalatedCount: cases.filter(c => c.isEscalated).length,
      needsResponseCount: cases.filter(c => c.status === 'New').length
    };

    const insights = {
      casesAtRisk: cases.filter(c => c.slaDaysRemaining < 0),
      staleCases: cases.filter(c => c.daysOpen > 20),
      trendingCases: cases.filter(c => c.status === 'Working' && c.daysOpen < 5)
    };

    return { cases, summary, insights };
  }

  function loadDashboardData() {
    state.isLoading = true;
    state.error = null;
    updateUI();

    setTimeout(() => {
      try {
        const mockData = generateMockData();
        state.cases = mockData.cases;
        state.summary = mockData.summary;
        state.insights = mockData.insights;
        state.lastRefreshTime = new Date().toLocaleTimeString();
        state.isLoading = false;
        updateUI();
      } catch (error) {
        state.error = 'Error loading dashboard data';
        state.isLoading = false;
        updateUI();
      }
    }, 800);
  }

  function updateUI() {
    const loadingSpinner = document.getElementById('loadingSpinner');
    const errorContainer = document.getElementById('errorContainer');
    const tableContainer = document.getElementById('tableContainer');
    const noCasesMessage = document.getElementById('noCasesMessage');
    const insightsSection = document.getElementById('insightsSection');
    const refreshBtn = document.getElementById('refreshBtn');
    const lastRefreshText = document.getElementById('lastRefreshText');

    loadingSpinner.style.display = state.isLoading ? 'block' : 'none';
    errorContainer.style.display = state.error ? 'block' : 'none';
    refreshBtn.disabled = state.isLoading;

    if (state.error) {
      document.getElementById('errorMessage').textContent = state.error;
    }

    if (state.lastRefreshTime) {
      lastRefreshText.textContent = `Last refreshed: ${state.lastRefreshTime}`;
    }

    document.getElementById('totalOpenCount').textContent = state.summary.totalOpen || 0;
    document.getElementById('slaRiskCount').textContent = state.summary.slaRiskCount || 0;
    document.getElementById('escalatedCount').textContent = state.summary.escalatedCount || 0;
    document.getElementById('needsResponseCount').textContent = state.summary.needsResponseCount || 0;

    const hasInsights = (state.insights.casesAtRisk && state.insights.casesAtRisk.length > 0) ||
                       (state.insights.staleCases && state.insights.staleCases.length > 0) ||
                       (state.insights.trendingCases && state.insights.trendingCases.length > 0);

    if (hasInsights && !state.isLoading) {
      insightsSection.style.display = 'block';
      renderInsights();
    } else {
      insightsSection.style.display = 'none';
    }

    if (state.cases.length > 0 && !state.isLoading && !state.error) {
      tableContainer.style.display = 'block';
      noCasesMessage.style.display = 'none';
      renderTable();
    } else if (!state.isLoading && !state.error && state.cases.length === 0) {
      tableContainer.style.display = 'none';
      noCasesMessage.style.display = 'block';
    } else {
      tableContainer.style.display = 'none';
      noCasesMessage.style.display = 'none';
    }
  }

  function renderInsights() {
    const insightsGrid = document.getElementById('insightsGrid');
    insightsGrid.innerHTML = '';

    if (state.insights.casesAtRisk && state.insights.casesAtRisk.length > 0) {
      const col = document.createElement('div');
      col.className = 'slds-col slds-size_1-of-1 slds-medium-size_1-of-3';
      col.innerHTML = `
        <div class="insight-card risk-card">
          <div class="insight-header">
            <span class="slds-icon_container slds-icon-utility-warning slds-icon_container_circle slds-icon-action-error">
              <svg class="slds-icon slds-icon_small" aria-hidden="true">
                <use xlink:href="/assets/icons/utility-sprite/svg/symbols.svg#warning"></use>
              </svg>
            </span>
            <span class="slds-m-left_x-small">Cases at Risk</span>
          </div>
          <div class="insight-count">${state.insights.casesAtRisk.length}</div>
        </div>
      `;
      insightsGrid.appendChild(col);
    }

    if (state.insights.staleCases && state.insights.staleCases.length > 0) {
      const col = document.createElement('div');
      col.className = 'slds-col slds-size_1-of-1 slds-medium-size_1-of-3';
      col.innerHTML = `
        <div class="insight-card stale-card">
          <div class="insight-header">
            <span class="slds-icon_container slds-icon-utility-clock slds-icon_container_circle slds-icon-action-warning">
              <svg class="slds-icon slds-icon_small" aria-hidden="true">
                <use xlink:href="/assets/icons/utility-sprite/svg/symbols.svg#clock"></use>
              </svg>
            </span>
            <span class="slds-m-left_x-small">Stale Cases</span>
          </div>
          <div class="insight-count">${state.insights.staleCases.length}</div>
        </div>
      `;
      insightsGrid.appendChild(col);
    }

    if (state.insights.trendingCases && state.insights.trendingCases.length > 0) {
      const col = document.createElement('div');
      col.className = 'slds-col slds-size_1-of-1 slds-medium-size_1-of-3';
      col.innerHTML = `
        <div class="insight-card momentum-card">
          <div class="insight-header">
            <span class="slds-icon_container slds-icon-utility-trending slds-icon_container_circle slds-icon-action-success">
              <svg class="slds-icon slds-icon_small" aria-hidden="true">
                <use xlink:href="/assets/icons/utility-sprite/svg/symbols.svg#trending"></use>
              </svg>
            </span>
            <span class="slds-m-left_x-small">Resolution Momentum</span>
          </div>
          <div class="insight-count">${state.insights.trendingCases.length}</div>
        </div>
      `;
      insightsGrid.appendChild(col);
    }
  }

  function renderTable() {
    const tbody = document.getElementById('caseTableBody');
    tbody.innerHTML = '';

    state.cases.forEach((caseItem, index) => {
      const row = document.createElement('tr');
      row.className = 'slds-hint-parent';
      row.innerHTML = `
        <td data-label="#">
          <div class="slds-truncate">${index + 1}</div>
        </td>
        <td data-label="Case Number">
          <div class="slds-truncate">${caseItem.caseNumber}</div>
        </td>
        <td data-label="Subject">
          <div class="slds-truncate">${caseItem.subject}</div>
        </td>
        <td data-label="Priority">
          <div class="slds-truncate">${caseItem.priority}</div>
        </td>
        <td data-label="Status">
          <div class="slds-truncate">${caseItem.status}</div>
        </td>
        <td data-label="Days Open">
          <div class="slds-truncate">${caseItem.daysOpen}</div>
        </td>
        <td data-label="SLA Days Remaining">
          <div class="slds-truncate">${caseItem.slaDaysRemaining}</div>
        </td>
        <td data-label="Account">
          <div class="slds-truncate">${caseItem.accountName}</div>
        </td>
        <td data-label="Escalated">
          <div class="slds-truncate">${caseItem.isEscalated ? '✓' : ''}</div>
        </td>
      `;
      tbody.appendChild(row);
    });
  }

  function sortData(fieldName, direction) {
    const cloneData = [...state.cases];

    cloneData.sort((a, b) => {
      let aVal = a[fieldName];
      let bVal = b[fieldName];

      if (aVal === null || aVal === undefined) return direction === 'asc' ? 1 : -1;
      if (bVal === null || bVal === undefined) return direction === 'asc' ? -1 : 1;

      if (typeof aVal === 'string') aVal = aVal.toLowerCase();
      if (typeof bVal === 'string') bVal = bVal.toLowerCase();

      if (aVal < bVal) {
        return direction === 'asc' ? -1 : 1;
      } else if (aVal > bVal) {
        return direction === 'asc' ? 1 : -1;
      }
      return 0;
    });

    state.cases = cloneData;
  }

  function handleSort(event) {
    const th = event.target.closest('th');
    if (!th || !th.dataset.field) return;

    const fieldName = th.dataset.field;

    if (state.sortedBy === fieldName) {
      state.sortedDirection = state.sortedDirection === 'asc' ? 'desc' : 'asc';
    } else {
      state.sortedBy = fieldName;
      state.sortedDirection = 'asc';
    }

    sortData(state.sortedBy, state.sortedDirection);
    updateUI();
  }

  function init() {
    document.getElementById('refreshBtn').addEventListener('click', loadDashboardData);

    const tableHeaders = document.querySelectorAll('th[data-field]');
    tableHeaders.forEach(th => {
      th.addEventListener('click', handleSort);
    });

    loadDashboardData();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

