/* Metric Values */
.metric-value {
    font-size: 2rem;
    font-weight: 700;
    line-height: 1.2;
}

/* Insight Cards */
.insight-card {
    padding: 1rem;
    border-radius: 0.25rem;
    border-left: 4px solid;
    background-color: #ffffff;
    min-height: 100px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.insight-card.risk-card {
    border-left-color: #ea001e;
    background-color: rgba(234, 0, 30, 0.05);
}

.insight-card.stale-card {
    border-left-color: #ffb75d;
    background-color: rgba(255, 183, 93, 0.05);
}

.insight-card.momentum-card {
    border-left-color: #2e844a;
    background-color: rgba(46, 132, 74, 0.05);
}

.insight-header {
    display: flex;
    align-items: center;
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.insight-count {
    font-size: 2.5rem;
    font-weight: 700;
    text-align: center;
    margin-top: 0.5rem;
}

/* Responsive adjustments */
@media (max-width: 768px) {
    .metric-value {
        font-size: 1.5rem;
    }

    .insight-count {
        font-size: 2rem;
    }
}

/* Loading state */
.slds-is-relative {
    min-height: 200px;
}
